import React from "react";
import {
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { colors, fonts, fontWeights, borderRadius, getIconGradientColor, getLinearGradientColor } from "../styles/theme";

interface FeatureCardProps {
  title: string;
  icon: React.ReactNode;
  delay?: number;
  color?: string;
  index?: number; // Position in grid for gradient color calculation
  useGradientColor?: boolean; // Enable blue-to-purple gradient coloring
}

export const FeatureCard: React.FC<FeatureCardProps> = ({
  title,
  icon,
  delay = 0,
  color = colors.primary,
  index = 0,
  useGradientColor = false,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Calculate gradient color based on grid position if enabled
  const gradientColors = useGradientColor ? getIconGradientColor(index, 3) : null;
  const iconColor = gradientColors ? gradientColors.icon : color;
  const iconBg = gradientColors ? gradientColors.bg : `${color}15`;

  const slideProgress = spring({
    fps,
    frame: frame - delay,
    config: { damping: 15, stiffness: 100 },
  });

  const opacity = interpolate(frame - delay, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const slideY = interpolate(slideProgress, [0, 1], [50, 0]);
  const scale = interpolate(slideProgress, [0, 1], [0.8, 1]);

  return (
    <div
      style={{
        opacity,
        transform: `translateY(${slideY}px) scale(${scale})`,
        background: colors.surface,
        borderRadius: borderRadius.xl,
        padding: 32,
        // Use new glass card shadow with blue/purple accents
        boxShadow: "0 10px 15px -3px rgba(59, 130, 246, 0.08), 0 4px 6px -4px rgba(168, 85, 247, 0.08)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 20,
        minWidth: 220,
        border: `2px solid ${iconColor}20`,
      }}
    >
      <div
        style={{
          width: 72,
          height: 72,
          borderRadius: borderRadius.xl,
          background: iconBg,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: iconColor,
        }}
      >
        {icon}
      </div>
      <div
        style={{
          fontFamily: fonts.primary,
          fontSize: 20,
          fontWeight: fontWeights.semibold,
          color: colors.text,
          textAlign: "center",
        }}
      >
        {title}
      </div>
    </div>
  );
};

