// Industry Card for Use Cases section with gradient coloring
export const IndustryCard: React.FC<{
  name: string;
  icon: React.ReactNode;
  delay?: number;
  index?: number; // Position for gradient color calculation
  total?: number; // Total number of items for linear gradient
  useGradientColor?: boolean;
}> = ({ name, icon, delay = 0, index = 0, total = 5, useGradientColor = false }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Calculate gradient color for linear layout
  const gradientColors = useGradientColor ? getLinearGradientColor(index, total) : null;
  const iconColor = gradientColors ? gradientColors.icon : colors.primary;

  const slideProgress = spring({
    fps,
    frame: frame - delay,
    config: { damping: 15, stiffness: 100 },
  });

  const opacity = interpolate(frame - delay, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const slideX = interpolate(slideProgress, [0, 1], [60, 0]);

  return (
    <div
      style={{
        opacity,
        transform: `translateX(${slideX}px)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 16,
      }}
    >
      <div
        style={{
          width: 100,
          height: 100,
          borderRadius: borderRadius.xl,
          background: colors.surface,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          // Use new glass card shadow
          boxShadow: "0 10px 15px -3px rgba(59, 130, 246, 0.08), 0 4px 6px -4px rgba(168, 85, 247, 0.08)",
          color: iconColor,
        }}
      >
        {icon}
      </div>
      <div
        style={{
          fontFamily: fonts.primary,
          fontSize: 18,
          fontWeight: fontWeights.medium,
          color: colors.text,
        }}
      >
        {name}
      </div>
    </div>
  );
};
